    },
    {
      "card_ids": ["C26"],
      "claim": "Oxcarbazepine, a closely related dibenzazepine carboxamide, has an absolute oral bioavailability of >95% in humans, supporting high oral bioavailability for the same scaffold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C27"],
      "claim": "Licarbazepine, the reduced analogue of the same carbamazepine family, has a mean absolute bioavailability of 89% after oral dosing in healthy adults.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C17"],
      "claim": "Eslicarbazepine, derived from the same dibenzazepine carboxamide core, has an oral bioavailability of >90% in humans, further supporting high absorption for this structural class.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "The query is carbamazepine, a dibenzazepine carboxamide. All transferable experimental evidence from close structural analogues—carbamazepine epoxide, oxcarbazepine, licarbazepine, and eslicarbazepine—shows high oral bioavailability (60% to >95%), strongly supporting F >= 20%.",
  "evidence_gaps": [
    "No direct absolute oral bioavailability record for carbamazepine itself is present in the supplied evidence set; the prediction relies on close structural analogues.",
    "Some records report absorption/recovery rather than formal absolute F, but direct absolute F values are available for key analogues."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

